#!/usr/bin/env python3
"""Record completed native proof output and exact executable/source identities."""
import argparse,hashlib,json,platform,re,subprocess
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
p=argparse.ArgumentParser();p.add_argument('--exit-code',type=int,required=True);p.add_argument('--binary',type=Path,required=True);args=p.parse_args()
log=ROOT/'audit/v04/evidence/trust-native-full.log';text=log.read_text()
turns=[dict(zip(['turn','expected','source_artifact','decoded_bytecode','epoch'],map(int,row))) for row in re.findall(r'^\s*(\d+)\s+(\d+)\s+(\d+)\s+(\d+)\s+(\d+)\s+COMMIT\s*$',text,re.M)]
