result={'status':'passed' if passed else 'failed','source_commit':'c4777b7015fe8ff47fdfa48d18606c49aace7d97','absorbed_pr':'https://github.com/mech-lang/mech/pull/829','absorbed_revision':'9ae5c00e0184fe341d2ff2bdc590ede712009d2f','source_modifications':{path:hash_file(ROOT/path) for path in files},'scope':'native canonical parser and semantic frontend, source and decoded artifacts, engine resident primitive execution','command':'CARGO_TARGET_DIR=/private/tmp/mech-v04-target-product cargo run -p mech --locked --offline --no-default-features --example r-stack-trust-proof --features r_stack_trust_proof -- --dump all','features':'r_stack_trust_proof','default_features':False,'exit_code':args.exit_code,'binary':{'path':str(args.binary),'sha256':hash_file(args.binary)},'environment':{'platform':platform.platform(),'rustc':subprocess.check_output(['rustc','--version'],text=True).strip()},'source':(ROOT/'examples/r-stack-proof/trust-program.mec').read_text(),'source_artifact_revision':re.search(r'artifact revision\s*:\s*([0-9a-f]+)',text).group(1) if re.search(r'artifact revision\s*:\s*([0-9a-f]+)',text) else None,'turns':turns,'checks':re.findall(r'^\[PASS\] (.+)$',text,re.M),'perturbation':{'expected':[7,25,79],'passed':'resident outputs: PASS — 7, 25, 79' in text},'missing_catalog_rejected':'missing catalog: PASS — activation rejected' in text,'full_transcript':{'path':'audit/v04/evidence/trust-native-full.log','sha256':hash_file(log)}}
