(ROOT/'audit/v04/evidence/trust-native.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps({'status':result['status'],'turns':len(turns),'checks':len(result['checks'])}));raise SystemExit(0 if passed else 1)
